133	
134	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
135	    @Override
136	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
137	        normalizeAndValidate(ownerFieldsDto);
138	        HttpHeaders headers = new HttpHeaders();
139	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
140	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
141	        owner.setNamesakeCount(countNamesakes(owner));
142	        owner.setBulkSignupWarning(computeBulkSignupWarning(owner.getRegistrationDate()));
143	        assignHousehold(owner, ownerFieldsDto);
144	        this.clinicService.saveOwner(owner);
145	        AUDIT.info("owner created: id={} customerCode={} registrationDate={}",
146	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
147	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
148	        headers.setLocation(UriComponentsBuilder.newInstance()
149	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
150	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
151	    }
152	
153	    /**
154	     * Prepares a new owner's payload for persistence, applying every rule an incoming owner must satisfy before it is
155	     * saved. The address is first normalized to its canonical stored form and written back onto the payload; required
156	     * fields are then checked (so an address that is blank after normalization is rejected); the telephone is
157	     * normalized to its canonical stored form, written back onto the payload and rejected if another owner already uses
158	     * it; the email is canonicalized; and the registration date is resolved to its effective business day. The
159	     * effective registration date is the supplied value or, when none was supplied, the current server date; when it
160	     * falls on a weekend it is rolled forward to the following Monday and that adjusted date is written back onto the
161	     * payload, so every value derived from it (such as the membership number's year segment and the per-day limit)
162	     * uses the adjusted date. The payload is mutated in place so the caller can map and save it directly.
163	     *
164	     * @param ownerFieldsDto the incoming owner payload, mutated in place
165	     * @throws MissingOwnerFieldsException if any required field is missing or blank
166	     * @throws DuplicateTelephoneException if another owner already uses the normalized telephone
167	     */
168	    private void normalizeAndValidate(OwnerFieldsDto ownerFieldsDto) {
169	        ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
170	        validateRequiredFields(ownerFieldsDto);
171	        String telephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
172	        ownerFieldsDto.setTelephone(telephone);
173	        requireUniqueTelephone(telephone);
174	        requireUniqueHousehold(ownerFieldsDto);
175	        requireCityHasCapacity(ownerFieldsDto.getCity());
176	        LocalDate registrationDate = resolveRegistrationDate(ownerFieldsDto);
177	        ownerFieldsDto.setRegistrationDate(registrationDate);
178	        requireDailyLimitNotReached(registrationDate);
179	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
180	    }
181	
182	    /**
183	     * Resolves an owner's effective registration date and rolls it onto a business day. The effective date is the value
184	     * supplied on the payload, or the current server date when none was supplied; when that date is a Saturday or
185	     * Sunday it is rolled forward to the following Monday. The returned date is always a business day.
186	     *
187	     * @param ownerFieldsDto the incoming owner payload
188	     * @return the effective registration date rolled forward onto a business day
189	     */
190	    private LocalDate resolveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
191	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
192	        if (effective == null) {
193	            effective = LocalDate.now();
194	        }
195	        while (effective.getDayOfWeek() == DayOfWeek.SATURDAY || effective.getDayOfWeek() == DayOfWeek.SUNDAY) {
196	            effective = effective.plusDays(1);
197	        }
198	        return effective;
199	    }
200	
201	    /**
202	     * Rejects creating an owner once the maximum number of owners for the adjusted business day has already been
203	     * reached. The cap is 100, so when 100 or more existing owners carry the given adjusted {@code registrationDate} no
204	     * further owner may be created for that day.
205	     *
206	     * @param registrationDate the adjusted business-day registration date of the owner being created
207	     * @throws DailyOwnerLimitExceededException if 100 or more owners have already been created for that day
208	     */
209	    private void requireDailyLimitNotReached(LocalDate registrationDate) {
210	        long createdThatDay = this.clinicService.findAllOwners().stream()
211	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
212	            .count();
213	        if (createdThatDay >= MAX_OWNERS_PER_DAY) {
214	            throw new DailyOwnerLimitExceededException(
215	                "the maximum number of owners for today has already been reached");
216	        }
217	    }
218	
219	    /**
220	     * Determines whether creating an owner for the given adjusted business-day registration date should carry a bulk
221	     * signup warning. The warning is raised once more than 80 owners already carry that {@code registrationDate},
222	     * i.e. this create is at least the 82nd for the day. Evaluated before the new owner is saved, so the count
223	     * reflects only owners that predate it.
224	     *
225	     * @param registrationDate the adjusted business-day registration date of the owner being created
226	     * @return {@code true} when more than 80 owners already exist for that day, {@code false} otherwise
227	     */
228	    private boolean computeBulkSignupWarning(LocalDate registrationDate) {
229	        long createdThatDay = this.clinicService.findAllOwners().stream()
230	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
231	            .count();
232	        return createdThatDay > BULK_SIGNUP_WARNING_THRESHOLD;
233	    }
234	
235	    /**
236	     * Builds an owner's {@code customerCode}, formatted {@code <CITY3>-<LAST3>-<NNNN>}. {@code CITY3} is the upper-cased
237	     * first three letters of the city, {@code LAST3} the upper-cased first three letters of the last name, and
238	     * {@code NNNN} a per-city 4-digit zero-padded sequence equal to one more than the number of owners already in that
239	     * city (e.g. {@code LON-SMI-0007}).
240	     *
241	     * @param city     the owner's city
242	     * @param lastName the owner's last name
243	     * @return the generated customer code
244	     */
245	    private String generateCustomerCode(String city, String lastName) {
246	        String cityPrefix = city.substring(0, Math.min(3, city.length())).toUpperCase();
247	        String lastPrefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
248	        int sequence = (int) this.clinicService.findAllOwners().stream()
249	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
250	            .count() + 1;
251	        return String.format("%s-%s-%04d", cityPrefix, lastPrefix, sequence);
252	    }
253	
254	    /**
255	     * Counts how many existing owners already share the given owner's first and last name, compared
256	     * case-insensitively. Invoked before the new owner is saved, so the result reflects only owners that predate this
257	     * create; it is zero when the owner's name is unique.
258	     *
259	     * @param owner the newly mapped owner about to be saved
260	     * @return the number of existing owners sharing the same first and last name (case-insensitively)
261	     */
262	    private int countNamesakes(Owner owner) {
263	        String firstName = owner.getFirstName();
264	        String lastName = owner.getLastName();
265	        return (int) this.clinicService.findAllOwners().stream()
266	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
267	                && lastName.equalsIgnoreCase(existing.getLastName()))
268	            .count();
269	    }
270	
271	    /**
272	     * Rejects an owner payload that omits or leaves blank any required field. Bean Validation already rejects missing
273	     * ({@code null}) required fields, but permits values that are blank (empty or whitespace-only) for fields without a
274	     * stricter pattern, so this check enforces the "missing or blank" rule uniformly across every required field.
275	     *
276	     * @param ownerFieldsDto the owner payload to validate
277	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or telephone is missing or blank
278	     */
279	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
280	        List<String> missingFields = new ArrayList<>();
281	        requireText(missingFields, "firstName", ownerFieldsDto.getFirstName());
282	        requireText(missingFields, "lastName", ownerFieldsDto.getLastName());
283	        requireText(missingFields, "address", ownerFieldsDto.getAddress());
284	        requireText(missingFields, "city", ownerFieldsDto.getCity());
285	        requireText(missingFields, "telephone", ownerFieldsDto.getTelephone());
286	        if (!missingFields.isEmpty()) {
287	            throw new MissingOwnerFieldsException(missingFields);
288	        }
289	    }
290	
291	    private void requireText(List<String> missingFields, String fieldName, String value) {
292	        if (value == null || value.isBlank()) {
293	            missingFields.add(fieldName);
294	        }
295	    }
296	
297	    /**
298	     * Normalizes an optional owner email. A syntactically valid address is already enforced by Bean Validation on the
299	     * request payload, so this only canonicalizes the value that gets stored and returned by lower-casing it. A missing
300	     * (blank or {@code null}) email is left untouched, since the field is optional.
301	     *
302	     * @param email the raw email value from the request, may be {@code null}
303	     * @return the lower-cased email, or the original value when none was supplied
304	     */
305	    private String normalizeEmail(String email) {
306	        if (email == null || email.isBlank()) {
307	            return email;
308	        }
309	        return email.toLowerCase();
310	    }
311	
312	    /**
313	     * Rejects creating an owner whose normalized telephone is already used by another owner. Existing owners' stored
314	     * telephones are canonicalized the same way before comparison, so the rule holds regardless of how their number was
315	     * originally formatted.
316	     *
317	     * @param telephone the normalized telephone of the owner being created
318	     * @throws DuplicateTelephoneException if any existing owner already uses the same normalized telephone
319	     */
320	    private void requireUniqueTelephone(String telephone) {
321	        boolean inUse = this.clinicService.findAllOwners().stream()
322	            .map(existing -> telephoneNormalizer.canonicalize(existing.getTelephone()))
323	            .anyMatch(telephone::equals);
324	        if (inUse) {
325	            throw new DuplicateTelephoneException("telephone is already in use by another owner");
326	        }
327	    }
328	
329	    /**
330	     * Rejects creating an owner whose city (compared case-insensitively) already contains the maximum number of
331	     * owners. The cap is 50, so a city holding 50 or more owners is full and no further owner may be created there.
332	     *
333	     * @param city the city of the owner being created
334	     * @throws OwnerCityFullException if the city already contains 50 or more owners
335	     */
336	    private void requireCityHasCapacity(String city) {
337	        long cityOwners = this.clinicService.findAllOwners().stream()
338	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
339	            .count();
340	        if (cityOwners >= MAX_OWNERS_PER_CITY) {
341	            throw new OwnerCityFullException("the owner's city already contains the maximum number of owners");
342	        }
343	    }
344	
345	    /**
346	     * Rejects creating an owner who shares a household (see {@link #findHouseholdMembers}) with an existing owner,
347	     * unless the request opts in by setting {@code sharesHousehold} to {@code true}.
348	     *
349	     * @param ownerFieldsDto the incoming owner payload
350	     * @throws DuplicateOwnerException if another owner already belongs to the same household and the request does not
351	     *                                 set {@code sharesHousehold}
352	     */
353	    private void requireUniqueHousehold(OwnerFieldsDto ownerFieldsDto) {
354	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
355	            return;
356	        }
357	        if (!findHouseholdMembers(ownerFieldsDto).isEmpty()) {
358	            throw new DuplicateOwnerException(
359	                "an owner with the same last name and address already exists in this household");
360	        }
361	    }
362	
363	    /**
364	     * Finds the existing owners that belong to the same household as the given payload, i.e. those sharing both its
365	     * last name and address. The last name is compared case-insensitively after collapsing runs of whitespace to a
366	     * single space and trimming; the address is compared in its normalized form (see {@link AddressNormalizer}), so
367	     * incidental formatting differences and abbreviation variants do not affect membership.
368	     *
369	     * @param ownerFieldsDto the incoming owner payload
370	     * @return the existing owners in the same household, in the order {@link ClinicService#findAllOwners()} returns
371	     *         them; empty when none match
372	     */
373	    private List<Owner> findHouseholdMembers(OwnerFieldsDto ownerFieldsDto) {
374	        String lastName = collapseWhitespace(ownerFieldsDto.getLastName());
375	        String address = addressNormalizer.normalize(ownerFieldsDto.getAddress());
376	        return this.clinicService.findAllOwners().stream()
377	            .filter(existing -> collapseWhitespace(existing.getLastName()).equalsIgnoreCase(lastName)
378	                && addressNormalizer.normalize(existing.getAddress()).equals(address))
379	            .toList();
380	    }
381	
382	    /**
383	     * Canonicalizes a value for household comparison by trimming it and collapsing every run of whitespace to a single
384	     * space. Case is deliberately preserved here; callers compare the result case-insensitively.
385	     *
386	     * @param value the raw field value, may be {@code null}
387	     * @return the whitespace-collapsed value, or an empty string when {@code null}
388	     */
389	    private String collapseWhitespace(String value) {
390	        if (value == null) {
391	            return "";
392	        }
393	        return value.strip().replaceAll("\\s+", " ");
394	    }
395	
396	    /**
397	     * Assigns the shared {@code householdId} for an owner joining an existing household. Only owners created with
398	     * {@code sharesHousehold} set to {@code true} that actually match an existing household (see
399	     * {@link #findHouseholdMembers}) are given an identifier; single owners keep a {@code null} household. The
400	     * identifier is derived deterministically from the household's last name and address, so every member of the same
401	     * household resolves to the same stable value regardless of creation order. Existing members that predate the
402	     * feature and still lack the identifier are backfilled so the whole household shares it.
403	     *
404	     * @param owner          the newly mapped owner about to be saved
405	     * @param ownerFieldsDto the incoming owner payload
406	     */
407	    private void assignHousehold(Owner owner, OwnerFieldsDto ownerFieldsDto) {
408	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
409	            return;
410	        }
411	        List<Owner> members = findHouseholdMembers(ownerFieldsDto);
412	        if (members.isEmpty()) {
413	            return;
414	        }
415	        String householdId = generateHouseholdId(ownerFieldsDto);
416	        owner.setHouseholdId(householdId);
417	        for (Owner member : members) {
418	            if (!householdId.equals(member.getHouseholdId())) {
419	                member.setHouseholdId(householdId);
420	                this.clinicService.saveOwner(member);
421	            }
422	        }
423	    }
424	
425	    /**
426	     * Derives a household's stable identifier, formatted {@code HH-<12 hex chars>}, from the case-insensitive,
427	     * whitespace-collapsed last name and the normalized address (see {@link AddressNormalizer}). Being a pure function
428	     * of those fields, it is identical for every owner in the same household and never changes over time.
429	     *
430	     * @param ownerFieldsDto the incoming owner payload
431	     * @return the household identifier
432	     */
433	    private String generateHouseholdId(OwnerFieldsDto ownerFieldsDto) {
434	        String key = collapseWhitespace(ownerFieldsDto.getLastName()).toLowerCase()
435	            + "\n" + addressNormalizer.normalize(ownerFieldsDto.getAddress()).toLowerCase();
436	        try {
437	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
438	            StringBuilder hex = new StringBuilder();
439	            for (int i = 0; i < 6; i++) {
440	                hex.append(String.format("%02X", digest[i]));
441	            }
442	            return "HH-" + hex;
443	        } catch (NoSuchAlgorithmException ex) {
444	            throw new IllegalStateException("SHA-256 is not available", ex);
445	        }
446	    }
447	
448	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
449	    @Override
450	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
451	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
452	        if (currentOwner == null) {
453	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
454	        }
455	        currentOwner.setAddress(ownerFieldsDto.getAddress());
456	        currentOwner.setCity(ownerFieldsDto.getCity());
457	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
458	        currentOwner.setLastName(ownerFieldsDto.getLastName());
459	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
460	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
461	        this.clinicService.saveOwner(currentOwner);
462	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
463	    }
464	
465	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
466	    @Transactional
467	    @Override
468	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
469	        Owner owner = this.clinicService.findOwnerById(ownerId);
470	        if (owner == null) {
471	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
472	        }
473	        this.clinicService.deleteOwner(owner);
474	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
475	    }
476	
477	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
478	    @Override
479	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
480	        Owner owner = this.clinicService.findOwnerById(ownerId);
481	        if (owner == null) {
482	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
483	        }
484	        HttpHeaders headers = new HttpHeaders();
485	        Pet pet = petMapper.toPet(petFieldsDto);
486	        owner.setId(ownerId);
487	        pet.setOwner(owner);
488	        pet.getType().setName(null);
489	        this.clinicService.savePet(pet);
490	        PetDto petDto = petMapper.toPetDto(pet);
491	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
492	            .buildAndExpand(pet.getId()).toUri());
493	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
494	    }
495	
496	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
497	    @Override
498	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
499	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
500	        if (currentOwner != null) {
501	            Pet currentPet = this.clinicService.findPetById(petId);
502	            if (currentPet != null) {
503	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
504	                currentPet.setName(petFieldsDto.getName());
505	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
506	                this.clinicService.savePet(currentPet);
507	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
508	            }
509	        }
510	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
511	    }
512	
513	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
514	    @Override
515	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
516	        HttpHeaders headers = new HttpHeaders();
517	        Visit visit = visitMapper.toVisit(visitFieldsDto);
518	        Pet pet = new Pet();
519	        pet.setId(petId);
520	        visit.setPet(pet);
521	        this.clinicService.saveVisit(visit);
522	        VisitDto visitDto = visitMapper.toVisitDto(visit);
523	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
524	            .buildAndExpand(visit.getId()).toUri());
525	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
526	    }
527	
528	
529	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
530	    @Override
531	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
532	        Owner owner = this.clinicService.findOwnerById(ownerId);
533	        if (owner != null) {
534	            Pet pet = owner.getPet(petId);
535	            if (pet != null) {
536	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
537	            }
538	        }
539	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
540	    }
541	}
